<script setup lang="ts">import{ref}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{request}from'../../api/client';const route=useRoute(),provider=ref<'STRIPE'|'PAYPAL'>('STRIPE'),creating=ref(false),result=ref<any>(null);async function buy(){creating.value=true;try{result.value=await request('/api/v1/payments/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:1,drama_id:Number(route.params.dramaId),provider:provider.value,currency:'USD',return_url:'http://127.0.0.1:1421/?payment=success',cancel_url:'http://127.0.0.1:1421/?payment=cancel'})});if(result.value.approve_url)window.open(result.value.approve_url,'_blank');ElMessage.success('支付订单已创建')}catch(e:any){ElMessage.error(e.message)}finally{creating.value=false}}</script>
<template><section><div class="page-title"><p class="eyebrow">CHECKOUT</p><h1>Complete your purchase</h1><p>Secure payment · Instant unlock after confirmation</p></div><el-card class="checkout"><h2>Drama #{{route.params.dramaId}}</h2><el-radio-group v-model="provider" class="providers"><el-radio-button label="STRIPE">Stripe</el-radio-button><el-radio-button label="PAYPAL">PayPal</el-radio-button></el-radio-group><el-alert :title="provider+' 支付'" description="创建真实支付订单后，由对应支付渠道完成付款。" type="info" show-icon/><el-button type="primary" size="large" class="pay-btn" :loading="creating" @click="buy">创建 {{provider}} 支付订单</el-button><div v-if="result" class="payment-result"><p>订单号：{{result.order_no}}</p><p>状态：{{result.status}}</p></div></el-card></section></template>